"""Constants shared across the server."""

BUCKET_ID = "robinlabdev/robinvault"
HF_HOST = "huggingface.co"
LISTING_TTL_S = 60
FILE_CACHE_SECONDS = 604800  # originals are large, ETag makes revalidation cheap

# How long a share link stays valid. The expiry is inside the signed payload, so
# editing the URL cannot extend it.
SHARE_TTL_SECONDS = 30 * 60
# Presentation (deck) share links are meant to be passed around: 90 days.
DECK_SHARE_TTL_SECONDS = 90 * 24 * 60 * 60

# Reserved bucket prefix holding the small grid previews generated by
# `scripts/tools/make_thumbs.py`. They are served on request but never listed.
THUMB_PREFIX = "_thumbs/"

# Tiny blurred placeholders + aspect ratios written by `scripts/tools/make_thumbs.py`.
LQIP_PATH = THUMB_PREFIX + "_lqip.json"

# Bucket folder holding the Claude skill files (.md) listed on /skills.
SKILLS_FOLDER = "Claude Skills"

BACKDROP_SCENES = ("sakura", "starfield", "aurora", "fireflies", "wallpaper")
WALLPAPER_FOLDER = "wallpapers"
